-- TEST ONLY: reduced local harness. Never apply to a live Supabase project.
-- Column types/defaults observed read-only 2026-10-26; constraints/triggers are not a full production clone.
create role authenticated nologin;
create role anon nologin;
create schema auth;
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
grant usage on schema auth, public to authenticated, anon;
grant execute on function auth.uid() to authenticated, anon;
create table public.alumnos (
  "id" bigint generated by default as identity not null,
  "nombre" text,
  "telefono" text,
  "categoria" text,
  "estado" text,
  "created_at" timestamp without time zone default now(),
  "fecha_ingreso" date default CURRENT_DATE,
  "edad" integer,
  "peso" numeric,
  "altura" numeric,
  "nivel" integer default 1,
  "bloque_actual" integer default 1,
  "record_personal" text,
  "mejor_tiempo" text,
  "estado_powerfit" text default 'EN CURSO'::text,
  "xp" integer default 0,
  "rango" text default 'Bronce'::text,
  "medalla" text default '🥉'::text,
  "streak" integer default 0,
  "puntos_semanales" integer default 0,
  "matatoa_mes" boolean default false,
  "record_semanal" text,
  "record_historico" text,
  "user_id" uuid,
  "email" text,
  "plan" text default 'Basico'::text,
  "estado_pago" text default 'Pendiente'::text,
  "fecha_pago" date,
  "fecha_vencimiento" date,
  "monto" integer default 0,
  "contacto_emergencia" text,
  "observaciones" text,
  "role" text,
  "bloques_premium" integer default 0,
  "generaciones_disponibles" integer default 6,
  "fecha_ultima_generacion" date,
  "nivel_matatoa" text default 'Iniciado'::text,
  "foto_url" text,
  "avatar_template" text default 'champion_red'::text not null,
  "terminos_aceptados" boolean default false not null,
  "terminos_version" text,
  "terminos_aceptados_at" timestamp with time zone,
  "fecha_nacimiento" date,
  "foto_storage_path" text,
  "rut" text,
  primary key (id)
);
alter table public.alumnos enable row level security;
create table public.planificaciones_generadas (
  "id" bigint generated by default as identity not null,
  "user_id" uuid,
  "alumno_id" bigint,
  "nombre_alumno" text,
  "objetivo" text,
  "nivel" text,
  "contenido" text,
  "created_at" timestamp with time zone default now(),
  primary key (id)
);
alter table public.planificaciones_generadas enable row level security;
create table public.powerfit_coach_assignments (
  "id" bigint generated by default as identity not null,
  "coach_user_id" uuid not null,
  "alumno_id" bigint not null,
  "active" boolean default true not null,
  "notes" text,
  "assigned_by" uuid,
  "created_at" timestamp with time zone default now() not null,
  "updated_at" timestamp with time zone default now() not null,
  primary key (id)
);
alter table public.powerfit_coach_assignments enable row level security;
create table public.powerfit_generation_adjustments (
  "id" bigint generated by default as identity not null,
  "alumno_id" bigint not null,
  "actor_user_id" uuid not null,
  "balance_before" integer not null,
  "balance_after" integer not null,
  "delta" integer not null,
  "reason" text not null,
  "created_at" timestamp with time zone default now() not null,
  primary key (id)
);
alter table public.powerfit_generation_adjustments enable row level security;
create table public.powerfit_plan_events (
  "id" bigint generated by default as identity not null,
  "planificacion_id" bigint not null,
  "alumno_id" bigint not null,
  "event_type" text not null,
  "source" text,
  "actor_user_id" uuid,
  "actor_role" text,
  "reason" text,
  "metadata" jsonb default '{}'::jsonb not null,
  "created_at" timestamp with time zone default now() not null,
  primary key (id)
);
alter table public.powerfit_plan_events enable row level security;
create table public.powerfit_plan_metadata (
  "planificacion_id" bigint not null,
  "source" text default 'legacy'::text not null,
  "requested_source" text,
  "status" text default 'active'::text not null,
  "source_ref" text,
  "created_by" uuid,
  "creator_role" text,
  "voided_at" timestamp with time zone,
  "voided_by" uuid,
  "void_reason" text,
  "created_at" timestamp with time zone default now() not null,
  "updated_at" timestamp with time zone default now() not null,
  primary key (planificacion_id)
);
alter table public.powerfit_plan_metadata enable row level security;
revoke all on all tables in schema public from authenticated, anon;
